import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { useNotifications } from '@/components/ui/notifications';
import { MutationConfig } from '@/lib/react-query';

import { getUsersQueryOptions } from './get-users';

export const updateUserRoleInputSchema = z.object({
  role: z.enum(['ADMIN', 'USER']),
});

export type UpdateUserRoleInput = z.infer<typeof updateUserRoleInputSchema>;

export type UpdateUserRoleDTO = {
  userId: string;
  data: UpdateUserRoleInput;
};

export const updateUserRole = ({ userId, data }: UpdateUserRoleDTO) => {
  return api.patch(`/users/${userId}/role`, data);
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      addNotification({
        type: 'success',
        title: 'User Role Updated',
      });
      queryClient.invalidateQueries({
        queryKey: getUsersQueryOptions().queryKey,
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateUserRole,
  });
};

import { Check, ChevronDown } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

import { useUpdateUserRole } from '../api/update-user-role';

type UserRole = 'ADMIN' | 'USER';

type UpdateUserRoleProps = {
  userId: string;
  currentRole: UserRole;
};

const roles: { label: string; value: UserRole }[] = [
  { label: 'Admin', value: 'ADMIN' },
  { label: 'User', value: 'USER' },
];

export const UpdateUserRole = ({ userId, currentRole }: UpdateUserRoleProps) => {
  const updateUserRoleMutation = useUpdateUserRole();

  const [isOpen, setIsOpen] = useState(false);
  const [selectedRole, setSelectedRole] = useState<UserRole>(currentRole);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedRole(currentRole);
  }, [currentRole]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (ref.current && !ref.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleRoleChange = (role: UserRole) => {
    if (role === selectedRole) {
      setIsOpen(false);
      return;
    }
    updateUserRoleMutation.mutate({ userId, data: { role } }, {
      onSuccess: () => {
        setSelectedRole(role);
        setIsOpen(false);
      },
    });
  };

  return (
    <div className="relative" ref={ref}>
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        disabled={updateUserRoleMutation.isPending}
        className="inline-flex items-center gap-1 rounded border border-gray-300 bg-white px-2 py-1 text-xs font-medium text-gray-700 shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50"
      >
        <Check className="size-3" />
        <span>{selectedRole === 'ADMIN' ? 'Admin' : 'User'}</span>
        <ChevronDown className="size-3 text-gray-400" />
      </button>

      {isOpen && (
        <div className="absolute right-0 z-10 mt-1 w-28 rounded-md border border-gray-200 bg-white py-1 shadow-lg">
          {roles.map((role) => (
            <button
              key={role.value}
              type="button"
              onClick={() => handleRoleChange(role.value)}
              disabled={updateUserRoleMutation.isPending || role.value === selectedRole}
              className={`flex w-full items-center gap-1 px-3 py-1.5 text-xs hover:bg-gray-100 ${
                role.value === selectedRole
                  ? 'font-semibold text-blue-600'
                  : 'text-gray-700'
              } ${
                role.value === selectedRole
                  ? 'cursor-not-allowed opacity-50'
                  : ''
              }`}
            >
              <Check
                className={`size-3 ${role.value === selectedRole ? 'opacity-100' : 'opacity-0'}`}
              />
              {role.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

import { Spinner } from '@/components/ui/spinner';
